#!/usr/bin/env python3
import sys

from client.__main__ import main

if __name__ == "__main__":
    sys.exit(main())

import argparse
import os
import sys

from .pull import PullError, pull
from .push import PushError, push
from .status import StatusError, status
from .sync import SyncError, sync

COMMANDS = ("push", "pull", "sync", "status")


def parse_args(argv):
    parser = argparse.ArgumentParser(prog="syncbox")
    subparsers = parser.add_subparsers(dest="command", required=True)

    for name in COMMANDS:
        sub = subparsers.add_parser(name)
        sub.add_argument("dir")
        sub.add_argument(
            "--server",
            default=os.environ.get("SYNCBOX_SERVER"),
            help="Server base URL (or SYNCBOX_SERVER)",
        )

    args = parser.parse_args(argv)

    if not args.server:
        parser.error("--server is required (or set SYNCBOX_SERVER)")

    return args


def run_push(args):
    try:
        result = push(args.dir, args.server)
    except PushError as exc:
        print(f"syncbox: {exc}", file=sys.stderr)
        return 1

    for key in result.uploaded:
        print(f"uploaded {key}")

    print(f"push complete: {len(result.uploaded)} uploaded, {len(result.skipped)} unchanged")
    return 0


def run_pull(args):
    try:
        result = pull(args.dir, args.server)
    except PullError as exc:
        print(f"syncbox: {exc}", file=sys.stderr)
        return 1

    for key in result.downloaded:
        print(f"downloaded {key}")

    print(f"pull complete: {len(result.downloaded)} downloaded, {len(result.skipped)} unchanged")
    return 0


def run_status(args):
    try:
        result = status(args.dir, args.server)
    except StatusError as exc:
        print(f"syncbox: {exc}", file=sys.stderr)
        return 1

    for key in result.to_upload:
        print(f"would upload   {key}")
    for key in result.to_download:
        print(f"would download {key}")

    print(
        f"status complete: {len(result.to_upload)} would upload, "
        f"{len(result.to_download)} would download, {len(result.unchanged)} unchanged"
    )
    return 0


def run_sync(args):
    try:
        result = sync(args.dir, args.server)
    except SyncError as exc:
        print(f"syncbox: {exc}", file=sys.stderr)
        return 1

    for key in result.uploaded:
        print(f"uploaded {key}")
    for key in result.downloaded:
        print(f"downloaded {key}")

    print(
        f"sync complete: {len(result.uploaded)} uploaded, "
        f"{len(result.downloaded)} downloaded, {len(result.unchanged)} unchanged"
    )
    return 0


def main(argv=None):
    args = parse_args(sys.argv[1:] if argv is None else argv)

    if args.command == "push":
        return run_push(args)
    if args.command == "pull":
        return run_pull(args)
    if args.command == "status":
        return run_status(args)
    if args.command == "sync":
        return run_sync(args)

    print(f"syncbox: '{args.command}' is not implemented yet", file=sys.stderr)
    return 1


if __name__ == "__main__":
    sys.exit(main())

import json
from collections import namedtuple
from datetime import datetime
from pathlib import Path

import requests

from .pull import download_file
from .push import local_files, sha256_file, upload_file

SyncResult = namedtuple("SyncResult", ["uploaded", "downloaded", "unchanged"])

# Manifest of the last known common state (key -> sha256), used to tell
# "changed on one side only" (plain push/pull) apart from a real conflict
# (changed on both sides since the last sync). Lives inside the synced
# directory so it survives between separate `syncbox sync` invocations, and
# is excluded from the set of files being synced.
STATE_FILENAME = ".syncbox-sync-state.json"


class SyncError(Exception):
    """Raised when sync can't complete because of a local or remote failure."""


def _state_path(root):
    return root / STATE_FILENAME


def load_baseline(root):
    path = _state_path(root)
    if not path.is_file():
        return {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except (OSError, ValueError):
        return {}


def save_baseline(root, baseline):
    path = _state_path(root)
    tmp = path.with_name(f"{path.name}.tmp")
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(baseline, f, sort_keys=True)
    tmp.replace(path)


def parse_modified_at(value):
    return datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()


def fetch_remote_meta(server, session, timeout):
    response = session.get(f"{server}/blobs", timeout=timeout)
    response.raise_for_status()
    return {entry["key"]: entry for entry in response.json()}


def resolve_action(key, local_sha, remote_sha, baseline):
    """Decide what to do for a key present with differing content on both
    sides. A file changed relative to the baseline on only one side is a
    plain push/pull; changed on both (or never seen before) is a conflict,
    resolved by the caller using mtime."""
    base_sha = baseline.get(key)
    if base_sha == remote_sha:
        return "upload"
    if base_sha == local_sha:
        return "download"
    return "conflict"


def sync(directory, server, session=None, timeout=10):
    root = Path(directory)
    if not root.is_dir():
        raise SyncError(f"not a directory: {directory}")

    server = server.rstrip("/")
    session = session or requests.Session()

    baseline = load_baseline(root)
    paths = {key: path for key, path in local_files(root).items() if key != STATE_FILENAME}
    local_hashes = {key: sha256_file(path) for key, path in paths.items()}

    uploaded = []
    downloaded = []
    unchanged = []
    new_baseline = {}

    try:
        remote_meta = fetch_remote_meta(server, session, timeout)
        remote_hashes = {key: meta["sha256"] for key, meta in remote_meta.items()}

        for key in sorted(set(local_hashes) | set(remote_hashes)):
            local_sha = local_hashes.get(key)
            remote_sha = remote_hashes.get(key)

            if local_sha == remote_sha:
                unchanged.append(key)
                new_baseline[key] = local_sha
                continue

            if remote_sha is None:
                action = "upload"
            elif local_sha is None:
                action = "download"
            else:
                action = resolve_action(key, local_sha, remote_sha, baseline)
                if action == "conflict":
                    local_mtime = paths[key].stat().st_mtime
                    remote_mtime = parse_modified_at(remote_meta[key]["modified_at"])
                    action = "upload" if local_mtime >= remote_mtime else "download"

            if action == "upload":
                upload_file(server, session, key, paths[key], timeout)
                uploaded.append(key)
                new_baseline[key] = local_sha
            else:
                download_file(server, session, key, root, timeout)
                downloaded.append(key)
                new_baseline[key] = remote_sha
    except requests.exceptions.RequestException as exc:
        raise SyncError(f"could not reach server at {server}: {exc}") from exc

    save_baseline(root, new_baseline)

    return SyncResult(uploaded=uploaded, downloaded=downloaded, unchanged=unchanged)

import hashlib
from collections import namedtuple
from pathlib import Path
from urllib.parse import quote

import requests

PushResult = namedtuple("PushResult", ["uploaded", "skipped"])


class PushError(Exception):
    """Raised when push can't complete because of a local or remote failure."""


def sha256_file(path, chunk_size=1024 * 1024):
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            digest.update(chunk)
    return digest.hexdigest()


def local_files(root):
    """Map POSIX-relative key -> filesystem path for every file under root."""
    return {
        path.relative_to(root).as_posix(): path
        for path in sorted(root.rglob("*"))
        if path.is_file()
    }


def fetch_remote_hashes(server, session, timeout):
    response = session.get(f"{server}/blobs", timeout=timeout)
    response.raise_for_status()
    return {entry["key"]: entry["sha256"] for entry in response.json()}


def files_to_upload(local_hashes, remote_hashes):
    """Keys that are missing on the server or whose content differs."""
    return sorted(key for key, sha in local_hashes.items() if remote_hashes.get(key) != sha)


def upload_file(server, session, key, path, timeout):
    url = f"{server}/blobs/{quote(key, safe='/')}"
    with open(path, "rb") as f:
        response = session.put(url, data=f, timeout=timeout)
    response.raise_for_status()


def push(directory, server, session=None, timeout=10):
    root = Path(directory)
    if not root.is_dir():
        raise PushError(f"not a directory: {directory}")

    server = server.rstrip("/")
    session = session or requests.Session()
    paths = local_files(root)
    local_hashes = {key: sha256_file(path) for key, path in paths.items()}

    try:
        remote_hashes = fetch_remote_hashes(server, session, timeout)
        to_upload = files_to_upload(local_hashes, remote_hashes)
        for key in to_upload:
            upload_file(server, session, key, paths[key], timeout)
    except requests.exceptions.RequestException as exc:
        raise PushError(f"could not reach server at {server}: {exc}") from exc

    skipped = sorted(set(local_hashes) - set(to_upload))
    return PushResult(uploaded=to_upload, skipped=skipped)

import uuid
from collections import namedtuple
from pathlib import Path
from urllib.parse import quote

import requests

from .push import local_files, sha256_file

PullResult = namedtuple("PullResult", ["downloaded", "skipped"])


class PullError(Exception):
    """Raised when pull can't complete because of a local or remote failure."""


def fetch_remote_hashes(server, session, timeout):
    response = session.get(f"{server}/blobs", timeout=timeout)
    response.raise_for_status()
    return {entry["key"]: entry["sha256"] for entry in response.json()}


def files_to_download(remote_hashes, local_hashes):
    """Keys that are missing locally or whose content differs."""
    return sorted(key for key, sha in remote_hashes.items() if local_hashes.get(key) != sha)


def resolve_download_path(root, key):
    """Map a server-reported key to a path inside root, rejecting anything
    that would escape it. The server is not expected to hand out such keys,
    but pull shouldn't blindly trust it to write to the local filesystem."""
    if not key or key.startswith("/") or "\x00" in key:
        raise PullError(f"refusing to write unsafe key: {key!r}")

    segments = key.split("/")
    if ".." in segments:
        raise PullError(f"refusing to write unsafe key: {key!r}")

    root = root.resolve()
    candidate = (root / key).resolve()
    if candidate != root and root not in candidate.parents:
        raise PullError(f"refusing to write unsafe key: {key!r}")

    return candidate


def download_file(server, session, key, dest_root, timeout):
    url = f"{server}/blobs/{quote(key, safe='/')}"
    dest = resolve_download_path(dest_root, key)
    dest.parent.mkdir(parents=True, exist_ok=True)

    with session.get(url, timeout=timeout, stream=True) as response:
        response.raise_for_status()
        tmp = dest.parent / f".{dest.name}.syncbox-tmp-{uuid.uuid4().hex}"
        try:
            with open(tmp, "wb") as f:
                for chunk in response.iter_content(chunk_size=1024 * 1024):
                    f.write(chunk)
            tmp.replace(dest)
        except BaseException:
            tmp.unlink(missing_ok=True)
            raise


def pull(directory, server, session=None, timeout=10):
    root = Path(directory)
    if not root.is_dir():
        raise PullError(f"not a directory: {directory}")

    server = server.rstrip("/")
    session = session or requests.Session()
    paths = local_files(root)
    local_hashes = {key: sha256_file(path) for key, path in paths.items()}

    try:
        remote_hashes = fetch_remote_hashes(server, session, timeout)
        to_download = files_to_download(remote_hashes, local_hashes)
        for key in to_download:
            download_file(server, session, key, root, timeout)
    except requests.exceptions.RequestException as exc:
        raise PullError(f"could not reach server at {server}: {exc}") from exc

    skipped = sorted(set(remote_hashes) - set(to_download))
    return PullResult(downloaded=to_download, skipped=skipped)

import hashlib
import os
import uuid
from datetime import datetime, timezone
from pathlib import Path

from flask import Flask, jsonify, request, send_file

# Reserved path segment used for atomic-write staging (see write_blob_atomic).
# Keys resolving into a directory with this name are rejected so temp files
# are never addressable through the public API.
TMP_DIR_NAME = ".syncbox-tmp"


class InvalidKeyError(Exception):
    """Raised when a key can't be safely mapped to a path inside the data dir."""


def resolve_blob_path(data_dir, key):
    if not key or key.startswith("/") or "\x00" in key:
        raise InvalidKeyError(key)

    segments = key.split("/")
    if ".." in segments or TMP_DIR_NAME in segments:
        raise InvalidKeyError(key)

    # U+FFFD is what invalid percent-encoded UTF-8 bytes decode to
    # (e.g. "%ff%fe") -- the original key bytes are unrecoverable.
    if "�" in key:
        raise InvalidKeyError(key)

    root = Path(data_dir).resolve()

    try:
        key.encode("utf-8", errors="strict")
        candidate = (root / key).resolve()
    except (UnicodeError, ValueError, OSError):
        raise InvalidKeyError(key)

    # Authoritative check: regardless of what the checks above missed, the
    # resolved path must stay inside root. Catches symlink escapes and any
    # traversal shape not caught by the segment/prefix checks above.
    if candidate != root and root not in candidate.parents:
        raise InvalidKeyError(key)

    return candidate


def write_blob_atomic(path, content):
    """Write content to path without ever exposing a partially-written file.

    Writes to a uniquely-named temp file inside a sibling ``.syncbox-tmp``
    directory (same parent as `path`, so guaranteed to be the same
    filesystem) and atomically renames it into place. A concurrent reader
    of `path` therefore always sees either the fully old file or the fully
    new one, never a torn write -- and concurrent writers of the same key
    each write their own temp file, so they never corrupt each other's data.

    Structural key validation (resolve_blob_path) can't catch every key the
    underlying filesystem refuses: some byte sequences that are valid UTF-8
    still aren't representable as a path entry on a given filesystem/locale
    and surface only once the OS actually tries to create/rename the file
    (EIO, ENOENT-after-write, EILSEQ "invalid or incomplete multibyte
    character", etc.), sometimes intermittently. Any such failure -- at
    mkdir, open, write, fsync, or rename -- means this key can't be stored,
    which is a 400 (invalid key) per the API contract, not a crash. We
    raise InvalidKeyError for any OSError/UnicodeError/ValueError from that
    pipeline so callers get a uniform result regardless of which step
    failed or which specific bytes triggered it.
    """
    tmp_dir = path.parent / TMP_DIR_NAME
    tmp_path = None

    try:
        tmp_dir.mkdir(parents=True, exist_ok=True)
        tmp_path = tmp_dir / f"{uuid.uuid4().hex}.tmp"
        with open(tmp_path, "wb") as f:
            f.write(content)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, path)
    except (OSError, UnicodeError, ValueError) as exc:
        if tmp_path is not None:
            tmp_path.unlink(missing_ok=True)
        raise InvalidKeyError(str(path)) from exc
    except BaseException:
        if tmp_path is not None:
            tmp_path.unlink(missing_ok=True)
        raise


def blob_exists(path):
    """Check whether `path` names an existing blob file.

    Path.is_file() already swallows the common "doesn't exist" errnos
    (ENOENT, ENOTDIR, EBADF, ELOOP) and returns False for those. Anything
    else it lets through -- e.g. EIO or EILSEQ from a key whose decoded
    bytes the filesystem can't handle -- which means "this key can't even
    be looked up", i.e. a 400 (invalid key), not an unhandled crash.
    """
    try:
        return path.is_file()
    except (OSError, UnicodeError, ValueError) as exc:
        raise InvalidKeyError(str(path)) from exc


def create_app(data_dir):
    app = Flask(__name__)
    app.config["DATA_DIR"] = data_dir

    @app.errorhandler(InvalidKeyError)
    def handle_invalid_key(error):
        return jsonify(error="invalid key"), 400

    @app.errorhandler(404)
    def handle_unrouted_blob_path(error):
        # A key Werkzeug's own routing can't match at all (e.g. one that
        # decodes to a literal "\n", which breaks the <path:key> regex)
        # never reaches our view functions, so it never reaches
        # resolve_blob_path either -- it surfaces here as a generic,
        # non-JSON 404 instead. That key is exactly as invalid as one
        # resolve_blob_path would reject, so treat it the same way: 400,
        # not an unexplained 404. Deliberate `return "", 404` from our own
        # view functions (blob genuinely missing) never raises, so it
        # never reaches this handler.
        if request.path.startswith("/blobs/"):
            return jsonify(error="invalid key"), 400
        return error

    @app.get("/healthz")
    def healthz():
        return "", 200

    @app.get("/blobs")
    def list_blobs():
        root = Path(data_dir)
        blobs = []
        for path in sorted(root.rglob("*")):
            if not path.is_file():
                continue
            relative = path.relative_to(root)
            if TMP_DIR_NAME in relative.parts:
                continue
            stat = path.stat()
            blobs.append(
                {
                    "key": relative.as_posix(),
                    "size": stat.st_size,
                    "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
                    "modified_at": datetime.fromtimestamp(
                        stat.st_mtime, tz=timezone.utc
                    )
                    .isoformat()
                    .replace("+00:00", "Z"),
                }
            )

        return jsonify(blobs), 200

    @app.put("/blobs/<path:key>")
    def put_blob(key):
        path = resolve_blob_path(data_dir, key)
        content = request.get_data()
        write_blob_atomic(path, content)

        return (
            jsonify(
                key=key,
                sha256=hashlib.sha256(content).hexdigest(),
                size=len(content),
            ),
            201,
        )

    @app.get("/blobs/<path:key>")
    def get_blob(key):
        path = resolve_blob_path(data_dir, key)
        if not blob_exists(path):
            return "", 404

        try:
            return send_file(path, mimetype="application/octet-stream")
        except (OSError, UnicodeError, ValueError) as exc:
            # send_file derives a Content-Disposition filename from the key;
            # Werkzeug rejects header values containing control characters
            # (e.g. a raw CR/LF byte in the key) with a plain ValueError,
            # not OSError -- same "invalid key" outcome as any other
            # filesystem-level failure, so it gets the same 400 treatment.
            raise InvalidKeyError(str(path)) from exc

    @app.delete("/blobs/<path:key>")
    def delete_blob(key):
        path = resolve_blob_path(data_dir, key)
        if not blob_exists(path):
            return "", 404

        try:
            path.unlink()
        except (OSError, UnicodeError, ValueError) as exc:
            raise InvalidKeyError(str(path)) from exc
        return "", 204

    return app
